const STEPS = [
  // 1 · Bienvenida: una promesa corta y las cuatro cosas que hace la app
  () => ({
    art: `<div class="onb-logo">${MARK}</div>
      <div class="onb-tiles">${[["routes", "obF1"], ["plan", "obF2"], ["map", "obF3"], ["balance", "obF4"]].map(([i, k], n) => `<button type="button" class="onb-tile" data-k="${i}" style="--i:${n}">${svg(ICON[i])}<span>${t(k)}</span></button>`).join("")}</div>`,
    title: t("obWelcomeT"), sub: t("obWelcomeS"), primary: t("obNext"),
    bind(root) { root.querySelector(".onb-tiles").addEventListener("click", (e) => { const b = e.target.closest(".onb-tile"); if (b) openPeek(b); }); },
  }),
  // 2 · Preferencias: idioma y apariencia, se aplican al instante
  () => ({
    art: `<div class="onb-group"><div class="onb-lbl">${t("obLang")}</div>
        <div class="seg" id="onbLang" role="group" aria-label="${t("obLang")}">${[["es", "Español"], ["en", "English"]].map(([v, n]) => `<button data-v="${v}" aria-label="${n}" aria-pressed="${v === getLang()}">${v.toUpperCase()}</button>`).join("")}</div></div>
      <div class="onb-group"><div class="onb-lbl">${t("appearance")}</div>
        <div class="seg" id="onbTheme" role="group" aria-label="${t("appearance")}">${[["auto", "themeAuto"], ["light", "themeLight"], ["dark", "themeDark"]].map(([v, k]) => `<button data-v="${v}" aria-label="${t(k)}" title="${t(k)}" aria-pressed="${v === getTheme()}">${svg(THEME_ICON[v])}</button>`).join("")}</div></div>`,
    title: t("obPrefT"), sub: t("obPrefS"), primary: t("obNext"),
    bind(root, api) {
      glassSeg(root.querySelector("#onbLang")); glassSeg(root.querySelector("#onbTheme"));
      root.querySelector("#onbLang").addEventListener("click", (e) => {
        const b = e.target.closest("button"); if (!b || b.dataset.v === getLang()) return;
        // Solo cambia la selección (el selector se desliza); los textos se actualizan en su sitio, sin reconstruir la pantalla
        root.querySelectorAll("#onbLang button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
        setLang(b.dataset.v); api.retext();
      });
      root.querySelector("#onbTheme").addEventListener("click", (e) => {
        const b = e.target.closest("button"); if (!b) return;
        setTheme(b.dataset.v);
        root.querySelectorAll("#onbTheme button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
      });
    },
  }),
  // 3 · Ubicación: explicar para qué antes del aviso del sistema
  () => ({
    art: `<div class="onb-mapw">${MAP_SVG}<i class="onb-me"></i></div>`,
    title: t("obLocT"), sub: t("obLocS"), note: t("obLocPriv"), primary: t("obLocOn"), secondary: t("obLocLater"),
    bind(root) { followRoute(root.querySelector(".onb-mapw")); },
    async onPrimary(api) {
      const p = await locate();
      api.setNote(p ? t("obLocOk") : t("obLocNo"), p ? "ok" : "warn");
      setTimeout(api.next, p ? 650 : 1500);
    },
  }),
  // 4 · Cómo se usa: la pantalla Rutas real de la app (buscador, resultados y ficha), para probarla de verdad
  () => ({
    art: `<div class="onb-live"><section class="screen" id="onbRoutes"></section></div>`,
    title: t("obTourT"), sub: t("obTourS"), primary: t("obStart"),
    async bind(root) {
      const { default: routes } = await import("./screens/routes.js");
      routes.reset(); routes.init(root.querySelector("#onbRoutes"));
    },
  }),
];

// El punto azul recorre la ruta de izquierda a derecha y el mapa se mueve debajo: la cámara siempre queda centrada en él.
function followRoute(box) {
  const cam = box.querySelector(".cam"), rt = cam.querySelector(".rt"), L = rt.getTotalLength();
  const place = (d) => { const p = rt.getPointAtLength(d), k = box.clientWidth / 300; cam.style.transform = `translate3d(${-(p.x - 150) * k}px, ${-(p.y - 110) * k}px, 0)`; };
  place(0);
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const SPEED = 34, RAMP = 1.2; // unidades por segundo; arranque suave
  let t0 = 0, fading = false;
  const dist = (t) => SPEED * (t < RAMP ? (t * t) / (2 * RAMP) : t - RAMP / 2);
  const tick = (now) => {
    if (!box.isConnected) return;
    if (!t0) t0 = now + 500;
    const t = Math.max(0, (now - t0) / 1000), d = dist(t);
    if (d >= L && !fading) {
      fading = true; box.classList.add("rs");
      setTimeout(() => { if (!box.isConnected) return; place(0); box.classList.remove("rs"); t0 = 0; fading = false; }, 420);
    }
    if (!fading) place(Math.min(d, L));
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

// ---------- Vistazos: al tocar una ficha de la bienvenida se abre una tarjeta de vidrio con un adelanto de esa parte de la app ----------
const TILE_TXT = { routes: "obF1", plan: "obF2", map: "obF3", balance: "obF4" };
// Cada vistazo es la propia app (mismo código, datos y componentes) en un marco recortado, y un guion la maneja sola:
// escribe en el buscador, toca resultados y abre las fichas, como lo haría una persona.
const GLIMPSE = { routes: () => frameHTML("routes"), plan: () => frameHTML("plan"), map: () => frameHTML("map"), balance: () => frameHTML("balance") };
const FW = 375, FH = 500;
function frameHTML(tab) {
  const cardW = Math.min(380, innerWidth - 40) - 36, s = Math.min(cardW / FW, (innerHeight - 48 - 120 - 36) / FH), w = Math.round(FW * s), h = Math.round(FH * s);
  const q = tab === "balance" ? "&balance=demo" : "";
  return `<div class="pk-frame pk-in" style="--i:0;width:${w}px;height:${h}px"><iframe title="" tabindex="-1" aria-hidden="true" data-tab="${tab}" src="/?tab=${tab}${q}" style="width:${FW}px;height:${FH}px;transform:scale(${s})"></iframe><i class="pk-shim"></i></div>`;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function drive(frame) {
  const fr = frame.querySelector("iframe"), tab = fr.dataset.tab, alive = () => frame.isConnected;
  // el marco nace con un about:blank «completo»: se espera a que cargue la app de verdad
  for (let i = 0; i < 200 && alive(); i++) { try { if (fr.contentWindow.location.search.includes("tab=") && fr.contentDocument.readyState === "complete") break; } catch {} await sleep(100); }
  const win = fr.contentWindow, doc = fr.contentDocument, $ = (q) => doc.querySelector(q), $$ = (q) => [...doc.querySelectorAll(q)];
  doc.head.insertAdjacentHTML("beforeend", "<style>:root{--tab-h:0px!important;--safe-b:0px!important}#tabbar{display:none!important}</style>");
  win.dispatchEvent(new win.Event("resize")); setTimeout(() => win.dispatchEvent(new win.Event("resize")), 900);   // el mapa se ajusta al marco sin la barra de pestañas
  const until = async (f, ms = 15000) => { const t0 = performance.now(); while (alive() && performance.now() - t0 < ms) { try { const r = f(); if (r) return r; } catch {} await sleep(120); } return null; };
  await until(() => !$("#boot") && $(`#s-${tab}:not([hidden]) *`));
  const input = (el) => el.dispatchEvent(new win.Event("input", { bubbles: true }));
  const typeInto = async (el, text, fire) => { el.value = ""; for (const ch of text) { if (!alive()) return; el.value += ch; fire && input(el); await sleep(150); } };
  const clear = (el) => { el.value = ""; input(el); };
  const close = () => ($("#detail .dclose") || $("#detail .dscrim"))?.click();
  const scroll = async (el, y, ms) => { el?.scrollTo({ top: y, behavior: "smooth" }); await sleep(ms); };
  let planned = false;
  const SCRIPT = {
    routes: async () => {                       // buscar F19, abrir la ficha, recorrer sus paradas y cerrar
      const q = $("#rq"); await typeInto(q, "F19", true); await sleep(1000);
      $("#rl summary")?.click(); await sleep(2400);
      await scroll($("#dbody"), 260, 1900); await scroll($("#dbody"), 0, 900); close(); await sleep(900); clear(q); await sleep(1300);
    },
    plan: async () => {                         // origen y destino, los resultados reales y el detalle de cada viaje
      if (!planned) {
        await typeInto($("#from"), "Portal Norte"); await sleep(250); await typeInto($("#to"), "Portal Américas"); await sleep(300);
        $("#pf")?.dispatchEvent(new win.Event("submit", { bubbles: true, cancelable: true }));
        if (!await until(() => $("#s-plan .card .top"), 20000)) return; planned = true; await sleep(1400);
      }
      const tops = $$("#s-plan .card .top");
      for (const t of tops.slice(0, 2)) { if (!alive()) return; t.click(); await sleep(1500); await scroll($("#s-plan .sbody"), 140, 1500); await scroll($("#s-plan .sbody"), 0, 800); }
    },
    map: async () => {                          // buscar un bus (F19): su recorrido y los buses en vivo, y abrir su ficha
      await sleep(1800);
      const q = $("#q"); await typeInto(q, "F19", true); await sleep(1300);
      const hit = $$("#sugg button").find((b) => /F19/.test(b.textContent)) || $("#sugg button");
      hit?.click(); await sleep(4800);
      $("#help")?.click(); await sleep(3200); ($("#lx") || $("#legend .x"))?.click(); await sleep(900);   // la leyenda explica el haz de luz y el aro de los buses
      clear(q); await sleep(1800);
    },
    balance: async () => {                      // «Revisar saldo»: espera la tarjeta, la detecta y muestra su ficha (lectura de ejemplo)
      await sleep(1200); $("#chk")?.click(); await sleep(4200); close(); await sleep(1600);
    },
  };
  frame.classList.add("ready");
  await sleep(700);
  while (alive()) { try { await SCRIPT[tab](); } catch { await sleep(800); } await sleep(600); }
}

function openPeek(tile) {
  const onb = document.getElementById("onb"); if (!onb || onb.querySelector(".onb-peek")) return;
  const key = tile.dataset.k, label = t(TILE_TXT[key]);
  const peek = document.createElement("div"); peek.className = "onb-peek";
  peek.innerHTML = `<div class="pk-bg"><i></i><i></i><i></i></div><div class="pk-card" role="dialog" aria-modal="true" aria-label="${label}"><div class="pk-top"><b>${label}</b><button type="button" class="pk-x" aria-label="${t("pkClose")}"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div><div class="pk-art">${GLIMPSE[key]()}</div></div>`;
  onb.append(peek);
  const card = peek.querySelector(".pk-card"), bg = peek.querySelector(".pk-bg"), ease = "cubic-bezier(.22,1,.36,1)";
  const fr = peek.querySelector(".pk-frame"); if (fr) drive(fr).catch(() => fr.classList.add("ready"));
  const morph = (fwd) => {
    if (!card.animate || matchMedia("(prefers-reduced-motion: reduce)").matches) return null;
    const a = tile.getBoundingClientRect(), b = card.getBoundingClientRect();
    const from = { transform: `translate(${a.left + a.width / 2 - (b.left + b.width / 2)}px, ${a.top + a.height / 2 - (b.top + b.height / 2)}px) scale(${a.width / b.width}, ${a.height / b.height})`, opacity: 0, filter: "blur(10px)" };
    const to = { transform: "none", opacity: 1, filter: "blur(0)" };
    return card.animate(fwd ? [from, to] : [to, from], { duration: fwd ? 520 : 380, easing: ease, fill: "both" });
  };
  bg.animate?.([{ opacity: 0 }, { opacity: 1 }], { duration: 420, easing: "ease-out" });
  morph(true);
  let closing = false;
  const close = (animate = true) => {
    if (closing) return; closing = true; removeEventListener("keydown", esc, true);
    const done = () => { peek.remove(); tile.focus?.({ preventScroll: true }); };
    if (!animate || !tile.isConnected) return done();
    bg.animate?.([{ opacity: 1 }, { opacity: 0 }], { duration: 320, fill: "forwards" });
    const a = morph(false); a ? (a.onfinish = done) : done();
  };
  const esc = (e) => { if (e.key === "Escape") { e.stopImmediatePropagation(); close(); } };
  addEventListener("keydown", esc, true);
  peek.querySelector(".pk-x").addEventListener("click", () => close());
  peek.addEventListener("click", (e) => { if (!e.target.closest(".pk-card")) close(); });
  swipeDismiss(card, { dim: bg, onDismiss: () => close(false) });
  peek.querySelector(".pk-x").focus({ preventScroll: true });
}

export function startOnboarding() {
  const lang0 = getLang();
  let n = 0, busy = false;
  const root = document.createElement("div");
  root.id = "onb"; root.className = "onb"; root.setAttribute("role", "dialog"); root.setAttribute("aria-modal", "true");
  root.innerHTML = `<div class="onb-top"><div class="onb-prog" role="list"></div><button class="onb-skip"></button></div>
    <div class="onb-body"></div>
    <div class="onb-foot"><p class="onb-note"></p><button class="btn full onb-go"></button><button class="btn ghost full onb-alt"></button></div>`;
  document.body.append(root); document.body.classList.add("onb-on");
  const $ = (s) => root.querySelector(s);
  const prog = $(".onb-prog"), body = $(".onb-body"), go = $(".onb-go"), alt = $(".onb-alt"), note = $(".onb-note"), skip = $(".onb-skip");

  const api = {
    next: () => (n < STEPS.length - 1 ? show(n + 1) : finish()),
    retext() {
      const s = STEPS[n]();
      body.querySelector("h1").textContent = s.title; body.querySelector(".onb-txt p").textContent = s.sub;
      go.textContent = s.primary; skip.textContent = t("obSkip"); paintProg();
      const L = body.querySelectorAll(".onb-lbl"); if (L[0]) { L[0].textContent = t("obLang"); L[1].textContent = t("appearance"); }
      body.querySelectorAll("#onbTheme button").forEach((x) => { const k = { auto: "themeAuto", light: "themeLight", dark: "themeDark" }[x.dataset.v]; x.setAttribute("aria-label", t(k)); x.title = t(k); });
    },
    setNote(txt, kind) { note.textContent = txt; note.dataset.k = kind || ""; note.hidden = !txt; },
  };

  function paintProg() {
    prog.innerHTML = STEPS.map((_, i) => `<button role="listitem" class="${i < n ? "done" : i === n ? "on" : ""}" ${i < n ? "" : "tabindex=\"-1\" disabled"} aria-label="${t("obStep", { n: i + 1, t: STEPS.length })}"><i></i></button>`).join("");
  }
  function show(i, dir = i > n ? 1 : -1) {
    const s = STEPS[i](); n = i; cur = s;
    paintProg();
    skip.textContent = t("obSkip"); skip.hidden = i === STEPS.length - 1;
    body.innerHTML = `<div class="onb-art">${s.art}</div><div class="onb-txt"><h1>${s.title}</h1><p>${s.sub}</p></div>`;
    body.dataset.dir = dir; body.classList.remove("in"); void body.offsetWidth; if (dir) body.classList.add("in");
    go.textContent = s.primary; alt.textContent = s.secondary || ""; alt.hidden = !s.secondary;
    api.setNote(s.note || "", "");
    s.bind?.(body, api);
    busy = false;
  }
  let cur = null;
  function finish() {
    try { localStorage.setItem(KEY, "1"); sessionStorage.setItem("ruta.tab", "home"); } catch {}   // quien termina la introducción llega siempre a Inicio
    import("./detail.js").then((m) => m.closeDetail()).catch(() => {});
    dispatchEvent(new Event("onbdone"));
    if (getLang() !== lang0) { location.replace(location.pathname); return; } // los textos de las pestañas se construyen al cargar
    document.body.classList.remove("onb-on");
    root.classList.add("out"); setTimeout(() => root.remove(), 320);
  }

  go.addEventListener("click", async () => {
    if (busy) return; busy = true;
    if (cur?.onPrimary) { go.disabled = alt.hidden = true; await cur.onPrimary(api); go.disabled = false; } else api.next();
  });
  alt.addEventListener("click", () => { if (!busy) api.next(); });
  skip.addEventListener("click", finish);
  prog.addEventListener("click", (e) => { const b = e.target.closest("button.done"); if (b) show([...prog.children].indexOf(b)); });
  addEventListener("keydown", (e) => { if (e.key === "Escape" && root.isConnected) finish(); });
  show(0, 0);
  go.focus({ preventScroll: true });
}
